//! ⏱️ Genuine Work completes within the original app opportunity and finite caller stock.
use semio_os_flow_host_source::work::FlowEvaluationWork;
use semio_framework_artifact_flow_flow::FlowHostSnapshot;
use neural_engine::{self as neural,ColdRetire,Dictionary,EvalChannels,OperatorInfo,TreeSnapshot};
use protocol::causal::transition::HistoryFoldIndex;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OriginalTurnFailure,StepContext,OperationId,Generation,close_original_retained_step};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_value::retained_clone::RetainedCloneClose;
use std::sync::Arc;
fn native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,loan:Option<u64>,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<T,(OriginalTurnFailure,Option<T>)>{let mut output=None;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,|cx|{let advance=|cx:&mut StepContext<'_>|{output=Some(run(cx)?);Ok(())};match loan{Some(fuel)=>cx.with_original_work_loan(fuel,1500,advance),None=>advance(cx)}}));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));match result{Ok(())=>Ok(output.unwrap()),Err(error)=>Err((error,output))}}
fn close<T:semio_framework_value::retirement::RetireOwned>(value:T,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,loan:Option<u64>){let mut original=Some(value);let mut retirement=RetainedCloneClose::default();for _ in 0..200_000{if original.is_none()&&retirement.is_empty(){return}native(caller,decoder,g,loan,|cx|cx.with_original_retirement(|cx|{let d=retirement.next_owner_demands::<T>(original.is_some(),&None,g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|if retirement.is_empty(){let turn=retirement.begin_granted(&mut original,grant);semio_framework_value::RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}else{retirement.step_granted(grant)})?;Ok(())})).unwrap();}panic!("original Work law exceeded its existing closure opportunity")}
#[derive(semio_framework_value::RetireOwned)]
struct Sources{source:FlowHostSnapshot,infos:Arc<HistoryFoldIndex<String,OperatorInfo>>,registry:neural::SharedRegistry,snapshot:Option<TreeSnapshot>,channels:Option<EvalChannels>,remaining:Vec<String>,pending:Vec<neural::PendingExtensionEval>,failure:Option<neural::OperatorWorkFailure>,original_failure:Option<OriginalTurnFailure>}
#[test]
fn original_evaluation_work_fits_the_existing_two_hundred_call_opportunity(){run_original_work(None)}
#[test]
fn original_evaluation_work_keeps_its_existing_two_hundred_calls_under_actual_one_fuel_and_512_items(){run_original_work(Some(1))}
fn run_original_work(loan:Option<u64>){
 let law:serde_json::Value=serde_json::from_str(include_str!("opportunity.json")).unwrap();let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 if let Some(fuel)=loan{assert_eq!(fuel,law["originalWorkLoan"]["fuel"].as_u64().unwrap());assert_eq!(law["maximumCalls"],law["originalWorkLoan"]["maximumCalls"]);assert_eq!(law["originalWorkLoan"]["maximumEventWork"],serde_json::json!(1));}
 let source:FlowHostSnapshot=semio_framework_pack_json::from_json_str(&fixture["source"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let(registry,mut registry_retirement)=neural::SharedRegistry::new(neural::Registry::new());let mut sources=Sources{source,infos:Arc::new(HistoryFoldIndex::new()),registry,snapshot:None,channels:None,remaining:Vec::new(),pending:Vec::new(),failure:None,original_failure:None};
 let pointer=sources.source.widgets.as_ptr();let mut work=FlowEvaluationWork::new(sources.infos.clone(),sources.registry.clone(),None,9,3);
 let g=RetainedCloneGrant{maximum_items:law["eventsPerCall"].as_u64().unwrap()as usize,maximum_copy_bytes:law["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:law["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:law["release"].as_u64().unwrap()as usize,maximum_depth:law["depth"].as_u64().unwrap()as usize};
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096},||Some(1000),1500,law["fuel"].as_u64().unwrap());let mut decoder=OriginalJobDecodeOwner::empty();let mut completed=false;let mut actual_work_matches=true;let mut physical_source_matches=true;
 for _ in 0..law["maximumCalls"].as_u64().unwrap(){let output=native(&mut caller,&mut decoder,g,loan,|cx|{let before=cx.original_total_fuel_remaining();let result=work.step(&sources.source,cx);actual_work_matches&=work.last_turn_work()==before-cx.original_total_fuel_remaining()&&loan.is_none_or(|fuel|work.last_turn_work()<=fuel);assert_eq!(work.step_progress(),cx.retained_progress());Ok(result)});
  physical_source_matches&=sources.source.widgets.as_ptr()==pointer;let output=match output{Ok(Ok(output))=>output,Ok(Err(error))=>{sources.failure=Some(error);break},Err((error,output))=>{sources.original_failure=Some(error);match output{Some(Ok(Some(output)))=>{sources.snapshot=Some(output.snapshot);sources.channels=Some(output.channels);sources.remaining=output.remaining;sources.pending=output.pending_extensions;},Some(Err(error))=>sources.failure=Some(error),_=>{}}break}};if let Some(output)=output{sources.snapshot=Some(output.snapshot);sources.channels=Some(output.channels);sources.remaining=output.remaining;sources.pending=output.pending_extensions;completed=true;break;}
 }

 let no_pending=sources.remaining.is_empty()&&sources.pending.is_empty();let no_failures=sources.failure.is_none()&&sources.original_failure.is_none();let output_matches=sources.channels.as_ref().is_some_and(|channels|{let outputs:std::collections::BTreeMap<_,_>=channels.outputs.iter().map(|(id,value)|(id,serde_json::from_str::<serde_json::Value>(&semio_framework_pack_json::to_json_string(value)).unwrap())).collect();serde_json::to_value(outputs).unwrap()==fixture["expectedOutputs"]});
 close(work,&mut caller,&mut decoder,g,loan);close(sources,&mut caller,&mut decoder,g,loan);
 for _ in 0..200_000{if registry_retirement.terminal_is_empty(){break}native(&mut caller,&mut decoder,g,loan,|cx|cx.with_original_retirement(|cx|{let d=semio_framework_value::RetirementDemand{copy_bytes:registry_retirement.next_copy_byte_demand()?,capacity_bytes:registry_retirement.next_capacity_byte_demand(g.maximum_copy_bytes)?,release_bytes:registry_retirement.next_release_byte_demand()?,depth:registry_retirement.next_depth_demand()?};close_original_retained_step(cx,d,|grant|{let result=registry_retirement.close_step(RetainedCloneGrant{maximum_items:1,..grant});semio_framework_value::RetainedWorkOutcome{work:registry_retirement.last_turn_work(),result}})?;Ok(())})).unwrap();}assert!(registry_retirement.terminal_is_empty());
 while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 assert!(completed,"real evaluation Work exhausted the unchanged app call opportunity");assert!(actual_work_matches&&physical_source_matches&&no_pending&&no_failures&&output_matches,"actual Work preserves original CPU, source, outputs and full refusal custody");
}
